ee:variables.ee:set-variable:
%dw 2.0
output application/java
import days from dw::core::Periods
fun text(v) = if (v is String) (if (isBlank(v)) null else trim(v)) else if (v is Number) (v as String) else null
fun matchesRe(s, re) = if (s is String) (s matches re) else false

var body = if (payload is Object) payload else {}
// The availability search returns no propertyList without a stay, so send the same defaults as get_property_details.
var checkin = (now() as Date) + days(p('default.checkinOffsetDays') as Number)
var checkout = checkin + days(p('default.nights') as Number)
var code = text(body.propertyCode)
var language = if (body.language == null) p('t03.defaultlanguage') else text(body.language)
---
{
	errors: [
		if (!(payload is Object)) "Request body must be a JSON object." else null,
		if (code == null) "propertyCode is required." else if (!matchesRe(code, /^[0-9]{1,20}$/)) "propertyCode must be 1 to 20 digits." else null,
		if (!matchesRe(language, /^[a-z]{2}(-[A-Za-z]{2,4})?$/)) "language must be a language code such as en or zh-CN." else null
	] filter ($ != null),
	request: {
		propertyCode: code,
		language: language,
		checkin: checkin as String {format: "yyyy-MM-dd"},
		checkout: checkout as String {format: "yyyy-MM-dd"},
		adults: p('default.adults') as Number,
		children: p('default.children') as Number
	}
}

%dw 2.0
// propertyList[] entry whose propertyCode matches the request; a single entry is taken as is.
output application/java
fun text(v) = if (v is String) (if (isBlank(v)) null else trim(v)) else if (v is Number) (v as String) else null
fun candidates(v): Array = if (v is Array) flatten(v map candidates($))
	else if (v is Object) (if (v.propertyList is Array) (v.propertyList filter ($ is Object))
		else if ((v.propertyCode != null) or (v.facilities != null)) [v]
		else flatten(valuesOf(v) map candidates($)))
	else []
var all = candidates(payload)
var code = vars.servicesRequest.propertyCode
---
(all filter ((c) -> text(c.propertyCode) == code))[0] default (if (sizeOf(all) == 1) all[0] else null)
